using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using System.IO;using System.Linq;
[InitializeOnLoad] public static class HunterTorchSetup{
 const string D="Assets/Demo/Characters/Hunter/Torch/";const string E="Evidence/hunter-torch-20261030/";
 static HunterTorchSetup(){EditorApplication.delayCall+=Build;}
 [MenuItem("Vampire Demo/Hunter/Build Left Hand Torch")]
 static void Build(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists(E+"setup.txt"))return;Directory.CreateDirectory(D);Directory.CreateDirectory(E);
 var scene=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueSettlement_Hunter.unity");string scenePath=AssetDatabase.GenerateUniqueAssetPath("Assets/Demo/Scenes/PrologueSettlement_HunterTorch.unity");EditorSceneManager.SaveScene(scene,scenePath);var bridge=Object.FindObjectOfType<HunterGameplayAnimator>();var a=bridge.animator;var player=bridge.gameObject;
 string before=Lighting(player);File.WriteAllText(E+"lighting-before.txt",before);
 string controllerPath=AssetDatabase.GenerateUniqueAssetPath(D+"Hunter_Torch.controller");AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(a.runtimeAnimatorController),controllerPath);var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(controllerPath);
 var mask=new AvatarMask();for(int i=0;i<(int)AvatarMaskBodyPart.LastBodyPart;i++)mask.SetHumanoidBodyPartActive((AvatarMaskBodyPart)i,false);mask.SetHumanoidBodyPartActive(AvatarMaskBodyPart.LeftArm,true);mask.SetHumanoidBodyPartActive(AvatarMaskBodyPart.LeftFingers,true);AssetDatabase.CreateAsset(mask,D+"LeftArm.mask");
 controller.AddLayer("Left Hand Torch");var layers=controller.layers;var layer=layers[layers.Length-1];layer.avatarMask=mask;layer.defaultWeight=1;controller.layers=layers;var source=AssetDatabase.LoadAllAssetsAtPath("Assets/Demo/ThirdParty/QuaterniusHunterAnimations/AnimationLibrary_Unity_Standard.fbx").OfType<AnimationClip>().First(c=>c.name=="Rig|Idle_Torch_Loop");var clip=Object.Instantiate(source);clip.name="LeftTorchHold";var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=true;AnimationUtility.SetAnimationClipSettings(clip,settings);AssetDatabase.CreateAsset(clip,D+"LeftTorchHold.anim");var state=layer.stateMachine.AddState("Torch Hold");state.motion=clip;state.mirror=true;a.runtimeAnimatorController=controller;
 var pose=player.AddComponent<HunterTorchPose>();pose.bridge=bridge;pose.layer=layers.Length-1;
 var torch=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Viking Village/Prefabs/Props/pf_torch_fire_01.prefab"));torch.name="Hunter Left Torch";torch.transform.position=Vector3.zero;torch.transform.rotation=Quaternion.identity;
 foreach(var t in torch.GetComponentsInChildren<Transform>(true)){GameObjectUtility.SetStaticEditorFlags(t.gameObject,0);GameObjectUtility.RemoveMonoBehavioursWithMissingScript(t.gameObject);t.gameObject.layer=0;}
 foreach(var col in torch.GetComponentsInChildren<Collider>(true))Object.DestroyImmediate(col);foreach(var l in torch.GetComponentsInChildren<Light>(true))l.enabled=false;
 foreach(var ps in torch.GetComponentsInChildren<ParticleSystem>(true)){var main=ps.main;main.loop=true;main.playOnAwake=true;main.simulationSpace=ParticleSystemSimulationSpace.World;}
 var materials=new System.Collections.Generic.Dictionary<Material,Material>();foreach(var renderer in torch.GetComponentsInChildren<Renderer>(true)){bool particle=renderer is ParticleSystemRenderer;renderer.sharedMaterials=renderer.sharedMaterials.Select(old=>{if(!old)return old;if(materials.TryGetValue(old,out var saved))return saved;var m=new Material(Shader.Find(particle?"Universal Render Pipeline/Particles/Unlit":"Universal Render Pipeline/Lit"));m.name="Torch_"+old.name;if(old.HasProperty("_MainTex"))m.SetTexture("_BaseMap",old.GetTexture("_MainTex"));if(old.HasProperty("_Color"))m.SetColor("_BaseColor",old.GetColor("_Color"));if(particle){bool additive=!renderer.name.Contains("smoke");m.SetFloat("_Surface",1);m.SetFloat("_Blend",additive?2:0);m.SetFloat("_SrcBlend",(float)UnityEngine.Rendering.BlendMode.SrcAlpha);m.SetFloat("_DstBlend",(float)(additive?UnityEngine.Rendering.BlendMode.One:UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha));m.SetFloat("_ZWrite",0);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.renderQueue=3000;}else if(old.HasProperty("_BumpMap")){m.SetTexture("_BumpMap",old.GetTexture("_BumpMap"));m.EnableKeyword("_NORMALMAP");}AssetDatabase.CreateAsset(m,AssetDatabase.GenerateUniqueAssetPath(D+m.name+".mat"));materials[old]=m;return m;}).ToArray();}
 PrefabUtility.SaveAsPrefabAsset(torch,D+"Hunter_TorchVisual.prefab");var hand=a.GetBoneTransform(HumanBodyBones.LeftHand);torch.transform.position=hand.position+hand.rotation*new Vector3(0,.06f,0);torch.transform.rotation=hand.rotation;torch.transform.localScale=Vector3.one*.65f;torch.transform.SetParent(hand,true);
 PrefabUtility.SaveAsPrefabAsset(player,AssetDatabase.GenerateUniqueAssetPath(D+"Hunter_TorchPlayer.prefab"));EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();string after=Lighting(player);File.WriteAllText(E+"lighting-after.txt",after);File.WriteAllText(E+"setup.txt","scene="+scenePath+"\nlightingEqual="+(before==after)+"\nTorchParticles="+torch.GetComponentsInChildren<ParticleSystem>(true).Length+" allTorchLightsDisabled="+torch.GetComponentsInChildren<Light>(true).All(l=>!l.enabled)+"\nhandScale="+hand.lossyScale+" torchWorldScale="+torch.transform.lossyScale+"\n");}
 static string Lighting(GameObject p){return string.Join("\n",p.GetComponentsInChildren<Light>(true).Where(l=>l.name!="Point light 2").Select(l=>l.name+" parent="+l.transform.parent.name+" pos="+l.transform.localPosition+" intensity="+l.intensity+" range="+l.range+" color="+l.color+" enabled="+l.enabled+" components="+string.Join(",",l.GetComponents<Component>().Where(c=>c).Select(c=>c.GetType().Name))));}
}
